package es.idynamicsax.ostris.config;
import es.idynamicsax.idax.tenant.*; import es.idynamicsax.ostris.security.OstrisJwtAuthFilter; import jakarta.servlet.DispatcherType; import org.springframework.context.annotation.*; import org.springframework.http.*; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableWebSecurity public class OstrisSecurityConfig {
 @Bean SecurityFilterChain chain(HttpSecurity h,OstrisJwtAuthFilter jwt,TenantContextFilter tenant)throws Exception{return h.cors(Customizer.withDefaults()).csrf(x->x.disable()).httpBasic(x->x.disable()).formLogin(x->x.disable()).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(x->x.authenticationEntryPoint((req,res,e)->res.sendError(HttpStatus.UNAUTHORIZED.value()))).authorizeHttpRequests(a->a.dispatcherTypeMatchers(DispatcherType.ASYNC,DispatcherType.ERROR).permitAll().requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/actuator/health/**","/actuator/info").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).addFilterAfter(tenant,OstrisJwtAuthFilter.class).build();}
 @Bean TenantContextFilter tenantContextFilter(TenantResolver r,AppUserResolver u){return new TenantContextFilter(r,u);}
}
